sp_widget.css:
.analytics-page {
    max-width: 1080px;
    margin: 0 auto;
    padding: 28px;
    color: #102a56;
}


/* HEADER */

.analytics-header {
    background: linear-gradient(
        135deg,
        #f4f3ff,
        #eef1ff
    );

    border: 1px solid #dfe3ff;
    border-radius: 18px;

    padding: 30px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 18px;
}


.eyebrow,
.card-eyebrow {
    font-size: 11px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #5267e8;
}


.analytics-header h1 {
    margin: 8px 0 5px;
    font-size: 28px;
    color: #082b62;
}


.analytics-header p {
    margin: 0;
    color: #66789b;
}


/* BUTTON */

.dashboard-btn {
    display: inline-block;

    padding: 11px 18px;

    border-radius: 9px;

    border: 1px solid #cbd5ef;

    background: white;

    color: #3156e8;

    text-decoration: none;

    font-size: 13px;

    font-weight: 600;
}


/* COMPANY */

.company-banner {
    background: white;

    border: 1px solid #dce3f0;

    border-radius: 14px;

    padding: 18px 22px;

    display: flex;

    align-items: center;

    gap: 15px;

    margin-bottom: 18px;
}


.company-avatar {
    width: 48px;
    height: 48px;

    border-radius: 12px;

    background: #5267e8;

    color: white;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;

    font-weight: 700;
}


.company-name {
    font-size: 17px;

    font-weight: 700;

    color: #092c62;
}


.company-id {
    font-size: 12px;

    color: #71809c;

    margin-top: 3px;
}


/* KPI */

.kpi-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 16px;

    margin-bottom: 18px;
}


.kpi-card {
    background: white;

    border: 1px solid #dce3f0;

    border-radius: 15px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 14px;
}


.kpi-icon {
    width: 42px;
    height: 42px;

    border-radius: 11px;

    background: #eef2ff;

    color: #5267e8;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 18px;
}


.kpi-label {
    font-size: 11px;

    color: #71809c;

    margin-bottom: 5px;
}


.kpi-value {
    font-size: 25px;

    font-weight: 700;

    color: #092c62;
}


/* CARD */

.analytics-card {
    background: white;

    border: 1px solid #dce3f0;

    border-radius: 17px;

    padding: 24px;

    margin-bottom: 18px;

    box-shadow:
        0 8px 25px rgba(
            40,
            65,
            110,
            0.05
        );
}


.card-header {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 22px;
}


.analytics-card h2 {
    margin: 6px 0 0;

    font-size: 18px;

    color: #173b70;
}


.record-count {
    font-size: 12px;

    padding: 6px 10px;

    border-radius: 8px;

    background: #f0f2ff;

    color: #5267e8;
}


/* FUNNEL */

.funnel-grid {
    display: grid;

    grid-template-columns:
        1fr auto 1fr auto 1fr auto 1fr;

    align-items: center;

    gap: 12px;
}


.funnel-item {
    text-align: center;

    background: #f8f9ff;

    border: 1px solid #e4e8f8;

    border-radius: 12px;

    padding: 18px 10px;
}


.funnel-number {
    display: block;

    font-size: 25px;

    font-weight: 700;

    color: #3156e8;
}


.funnel-label {
    display: block;

    font-size: 11px;

    color: #71809c;

    margin-top: 5px;
}


.funnel-arrow {
    color: #9aa7c2;

    font-size: 20px;
}


/* TABLE */

.table-wrapper {
    overflow-x: auto;
}


table {
    width: 100%;

    border-collapse: collapse;
}


th {
    text-align: left;

    font-size: 10px;

    letter-spacing: .7px;

    color: #7a89a5;

    background: #f8f9fd;

    padding: 13px;

    border-bottom: 1px solid #e5e9f1;
}


td {
    padding: 15px 13px;

    font-size: 12px;

    color: #385176;

    border-bottom: 1px solid #edf0f6;
}


.opp-title {
    font-weight: 700;

    color: #173b70;
}


.opp-id {
    font-size: 10px;

    color: #8794ac;

    margin-top: 3px;
}


.application-count {
    font-weight: 700;

    color: #3156e8;
}


.status-badge {
    display: inline-block;

    padding: 5px 10px;

    border-radius: 20px;

    background: #e8f8ef;

    color: #16834a;

    font-size: 11px;

    font-weight: 600;
}


.empty-state {
    text-align: center;

    padding: 35px;

    color: #8a97ad;
}


/* BOTTOM */

.bottom-grid {
    display: grid;

    grid-template-columns:
        1fr 1fr;

    gap: 18px;
}


.type-row,
.summary-row {
    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 13px 0;

    border-bottom: 1px solid #edf0f6;

    font-size: 13px;

    color: #536783;
}


.type-row strong,
.summary-row strong {
    color: #173b70;

    font-size: 14px;
}


.progress {
    height: 7px;

    background: #edf0f7;

    border-radius: 10px;

    margin-bottom: 8px;

    overflow: hidden;
}


.progress-fill {
    height: 100%;

    background: #5267e8;

    border-radius: 10px;
}


/* ERROR */

.error-message {
    padding: 16px;

    background: #fff2f2;

    border: 1px solid #ffd2d2;

    border-radius: 10px;

    color: #c62828;

    margin-bottom: 18px;
}


/* RESPONSIVE */

@media (max-width: 850px) {

    .kpi-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .funnel-grid {
        grid-template-columns: 1fr;
    }

    .funnel-arrow {
        transform: rotate(90deg);
        text-align: center;
    }

    .bottom-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 600px) {

    .analytics-header {
        flex-direction: column;

        align-items: flex-start;

        gap: 18px;
    }

    .kpi-grid {
        grid-template-columns: 1fr;
    }

}

sp_widget.script:
(function() {

    // =====================================================
    // SAMPLE RECRUITER / COMPANY
    // =====================================================

    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';

    // TechNova Solutions - CMP001
    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord('x_snc_campus360_company_master');

    if (!companyGR.get(companySysId)) {

        data.error = 'Company record could not be found.';
        return;

    }


    data.company = {
        name: companyGR.getValue('company_name'),
        id: companyGR.getValue('company_id')
    };


    // =====================================================
    // OPPORTUNITY ANALYTICS
    // =====================================================

    data.total_opportunities = 0;
    data.open_opportunities = 0;
    data.closed_opportunities = 0;
    data.job_opportunities = 0;
    data.internship_opportunities = 0;


    var oppGR =
        new GlideRecord('x_snc_campus360_placement_opportunity');

    oppGR.addQuery('company', companySysId);
    oppGR.query();

    while (oppGR.next()) {

        data.total_opportunities++;


        // Status
        var status =
            oppGR.getValue('status');

        if (status == 'Open') {

            data.open_opportunities++;

        } else {

            data.closed_opportunities++;

        }


        // Opportunity Type
        var opportunityType =
            oppGR.getValue('opportunity_type');

        if (opportunityType == 'Job') {

            data.job_opportunities++;

        }

        if (opportunityType == 'Internship') {

            data.internship_opportunities++;

        }

    }


    // =====================================================
    // APPLICATION ANALYTICS
    // =====================================================

    data.total_applications = 0;
    data.shortlisted = 0;
    data.interviews = 0;
    data.offers = 0;


    var appGR =
        new GlideRecord('x_snc_campus360_student_application');

    appGR.addQuery('opportunity.company', companySysId);
    appGR.query();

    while (appGR.next()) {

        data.total_applications++;


        // Shortlisted
        if (appGR.getValue('shortlisted') == 'true') {

            data.shortlisted++;

        }


        // Interview
        var interviewStatus =
            appGR.getValue('interview_status');

        if (interviewStatus &&
            interviewStatus != 'Not Scheduled') {

            data.interviews++;

        }


        // Offer
        var offerStatus =
            appGR.getValue('offer_status');

        if (offerStatus == 'Offered') {

            data.offers++;

        }

    }


    // =====================================================
    // OPPORTUNITY-WISE DATA
    // =====================================================

    data.opportunities = [];


    var opportunityGR =
        new GlideRecord('x_snc_campus360_placement_opportunity');

    opportunityGR.addQuery('company', companySysId);
    opportunityGR.orderBy('opportunity_title');
    opportunityGR.query();


    while (opportunityGR.next()) {

        var opportunitySysId =
            opportunityGR.getUniqueValue();


        var applicationCount = 0;


        var applicationGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );

        applicationGR.addQuery(
            'opportunity',
            opportunitySysId
        );

        applicationGR.query();


        while (applicationGR.next()) {

            applicationCount++;

        }


        data.opportunities.push({

            title:
                opportunityGR.getValue(
                    'opportunity_title'
                ),

            opportunity_id:
                opportunityGR.getValue(
                    'opportunity_id'
                ),

            type:
                opportunityGR.getDisplayValue(
                    'opportunity_type'
                ),

            location:
                opportunityGR.getValue(
                    'location'
                ),

            ctc:
                opportunityGR.getValue(
                    'ctc_stipend'
                ),

            status:
                opportunityGR.getDisplayValue(
                    'status'
                ),

            applications:
                applicationCount

        });

    }

})();
